contracts/recovery/PairRecovery.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title PairRecovery
 * @dev Contratto per registrare coppie SEA crittografate
 */
contract PairRecovery {
    // Struttura per memorizzare i dati del pair
    struct PairData {
        bytes encryptedPair; // Coppia SEA crittografata
        string username; // Alias dell'utente
        uint256 timestamp; // Timestamp della registrazione
        bool exists; // Flag per verificare esistenza
    }

    // Mapping: indirizzo utente -> dati del pair
    mapping(address => PairData) public userPairs;

    // Mapping: username -> indirizzo utente (per ricerca inversa)
    mapping(string => address) public usernameToAddress;

    // Eventi
    event PairRegistered(
        address indexed user,
        string username,
        uint256 timestamp
    );
    event PairUpdated(
        address indexed user,
        string newUsername,
        uint256 timestamp
    );
    event PairDeleted(address indexed user, uint256 timestamp);

    // Modificatori
    modifier pairExists(address user) {
        require(userPairs[user].exists, "Pair non trovato");
        _;
    }

    modifier pairNotExists(address user) {
        require(!userPairs[user].exists, "Pair gia' registrato");
        _;
    }

    modifier usernameNotTaken(string calldata username) {
        require(
            usernameToAddress[username] == address(0),
            "Username gia' in uso"
        );
        _;
    }

    /**
     * @dev Registra una nuova coppia SEA crittografata
     * @param encryptedPair Dati crittografati del pair SEA
     * @param username Alias dell'utente
     */
    function registerPair(
        bytes calldata encryptedPair,
        string calldata username
    ) external pairNotExists(msg.sender) usernameNotTaken(username) {
        require(encryptedPair.length > 0, "Dati crittografati non validi");
        require(bytes(username).length > 0, "Username non valido");

        userPairs[msg.sender] = PairData({
            encryptedPair: encryptedPair,
            username: username,
            timestamp: block.timestamp,
            exists: true
        });

        // Registra il mapping inverso
        usernameToAddress[username] = msg.sender;

        emit PairRegistered(msg.sender, username, block.timestamp);
    }

    /**
     * @dev Aggiorna i dati di un pair esistente
     * @param encryptedPair Nuovi dati crittografati del pair SEA
     * @param newUsername Nuovo username
     */
    function updatePair(
        bytes calldata encryptedPair,
        string calldata newUsername
    ) external pairExists(msg.sender) {
        require(encryptedPair.length > 0, "Dati crittografati non validi");
        require(bytes(newUsername).length > 0, "Username non valido");

        // Se l'username è diverso, verifica che non sia già in uso
        string memory oldUsername = userPairs[msg.sender].username;
        if (keccak256(bytes(oldUsername)) != keccak256(bytes(newUsername))) {
            require(
                usernameToAddress[newUsername] == address(0),
                "Username gia' in uso"
            );

            // Rimuovi il vecchio mapping
            delete usernameToAddress[oldUsername];
            // Aggiungi il nuovo mapping
            usernameToAddress[newUsername] = msg.sender;
        }

        userPairs[msg.sender].encryptedPair = encryptedPair;
        userPairs[msg.sender].username = newUsername;
        userPairs[msg.sender].timestamp = block.timestamp;

        emit PairUpdated(msg.sender, newUsername, block.timestamp);
    }

    /**
     * @dev Elimina il pair dell'utente
     */
    function deletePair() external pairExists(msg.sender) {
        // Rimuovi il mapping inverso
        delete usernameToAddress[userPairs[msg.sender].username];

        delete userPairs[msg.sender];

        emit PairDeleted(msg.sender, block.timestamp);
    }

    /**
     * @dev Ottiene i dati del pair di un utente tramite indirizzo
     * @param user Indirizzo dell'utente
     * @return encryptedPair Dati crittografati
     * @return username Alias dell'utente
     * @return timestamp Timestamp della registrazione
     * @return exists Se il pair esiste
     */
    function getPair(
        address user
    )
        external
        view
        returns (
            bytes memory encryptedPair,
            string memory username,
            uint256 timestamp,
            bool exists
        )
    {
        PairData memory data = userPairs[user];
        return (data.encryptedPair, data.username, data.timestamp, data.exists);
    }

    /**
     * @dev Ottiene i dati del pair di un utente tramite username
     * @param username Username dell'utente
     * @return user Indirizzo dell'utente
     * @return encryptedPair Dati crittografati
     * @return timestamp Timestamp della registrazione
     * @return exists Se il pair esiste
     */
    function getPairByUsername(
        string calldata username
    )
        external
        view
        returns (
            address user,
            bytes memory encryptedPair,
            uint256 timestamp,
            bool exists
        )
    {
        address userAddress = usernameToAddress[username];
        if (userAddress == address(0)) {
            return (address(0), "", 0, false);
        }

        PairData memory data = userPairs[userAddress];
        return (userAddress, data.encryptedPair, data.timestamp, data.exists);
    }

    /**
     * @dev Verifica se un utente ha registrato un pair tramite indirizzo
     * @param user Indirizzo dell'utente
     * @return True se il pair esiste
     */
    function hasPair(address user) external view returns (bool) {
        return userPairs[user].exists;
    }

    /**
     * @dev Verifica se un username è già registrato
     * @param username Username da verificare
     * @return True se l'username è già in uso
     */
    function isUsernameTaken(
        string calldata username
    ) external view returns (bool) {
        return usernameToAddress[username] != address(0);
    }

    /**
     * @dev Ottiene l'indirizzo associato a un username
     * @param username Username dell'utente
     * @return Indirizzo dell'utente (address(0) se non trovato)
     */
    function getAddressByUsername(
        string calldata username
    ) external view returns (address) {
        return usernameToAddress[username];
    }
}

contracts/relay/RelayPaymentRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

contract RelayPaymentRouter {
    // Struttura per rappresentare un relay
    struct Relay {
        string url;
        address payable relayAddress;
        bool isActive;
        uint256 registeredAt;
    }

    // Struttura per rappresentare una sottoscrizione
    struct Subscription {
        address user;
        address relay;
        uint256 startTime;
        uint256 endTime;
        uint256 amountPaid;
        uint256 mbAllocated; // MB allocati per questo mese
        bool isActive;
    }

    // Durata fissa della sottoscrizione (30 giorni)
    uint256 public constant SUBSCRIPTION_DURATION = 30 days;

    // Prezzo base per 1 GB (1000 MB) - 0.001 ETH per GB
    uint256 public constant PRICE_PER_GB = 0.001 ether;
    uint256 public constant MB_PER_GB = 1000;

    // Prezzo minimo per sottoscrizione (1 MB)
    uint256 public constant MIN_SUBSCRIPTION_AMOUNT = PRICE_PER_GB / MB_PER_GB;

    // Owner del contratto
    address public owner;

    // Fee per il contratto (2%)
    uint256 public contractFee = 200; // 200 = 2% (su base 10000)
    uint256 public constant FEE_DENOMINATOR = 10000;

    // Mappings
    mapping(address => Relay) public relays;
    mapping(address => address[]) public userSubscriptions; // user => relay addresses
    mapping(address => mapping(address => Subscription)) public subscriptions; // user => relay => subscription
    mapping(address => address[]) public relaySubscribers; // relay => user addresses

    // Array per tenere traccia di tutti i relay registrati
    address[] public registeredRelays;

    // Eventi
    event RelayRegistered(address indexed relayAddress, string url);
    event RelayDeactivated(address indexed relayAddress);
    event SubscriptionCreated(
        address indexed user,
        address indexed relay,
        uint256 amount,
        uint256 mbAllocated,
        uint256 endTime
    );
    event SubscriptionExpired(address indexed user, address indexed relay);
    event PaymentDistributed(address indexed relay, uint256 amount);
    event ContractFeeCollected(uint256 amount);

    // Modificatori
    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner can call this function");
        _;
    }

    modifier onlyActiveRelay() {
        require(
            relays[msg.sender].isActive,
            "Only active relays can call this function"
        );
        _;
    }

    modifier notPaused() {
        require(!emergencyPause, "Contract is paused");
        _;
    }

    constructor() {
        owner = msg.sender;
    }

    /**
     * @dev Registra un nuovo relay
     * @param _url URL del relay
     */
    function registerRelay(string memory _url) external notPaused {
        require(bytes(_url).length > 0, "URL cannot be empty");
        require(bytes(_url).length <= 200, "URL too long"); // Limite ragionevole
        require(!relays[msg.sender].isActive, "Relay already registered");

        relays[msg.sender] = Relay({
            url: _url,
            relayAddress: payable(msg.sender),
            isActive: true,
            registeredAt: block.timestamp
        });

        registeredRelays.push(msg.sender);

        emit RelayRegistered(msg.sender, _url);
    }

    /**
     * @dev Disattiva un relay (solo il proprietario del relay)
     */
    function deactivateRelay() external notPaused {
        require(relays[msg.sender].isActive, "Relay not active");
        relays[msg.sender].isActive = false;
        emit RelayDeactivated(msg.sender);
    }

    /**
     * @dev Verifica se un relay è registrato e attivo
     * @param _relayAddress Indirizzo del relay
     * @return bool True se il relay è registrato e attivo
     */
    function isRelayRegistered(
        address _relayAddress
    ) public view returns (bool) {
        return relays[_relayAddress].isActive;
    }

    /**
     * @dev Ottieni tutti i relay attivi
     * @return address[] Array degli indirizzi dei relay attivi
     */
    function getActiveRelays() external view returns (address[] memory) {
        address[] memory activeRelays = new address[](registeredRelays.length);
        uint256 activeCount = 0;

        for (uint256 i = 0; i < registeredRelays.length; i++) {
            if (relays[registeredRelays[i]].isActive) {
                activeRelays[activeCount] = registeredRelays[i];
                activeCount++;
            }
        }

        // Ridimensiona l'array al numero effettivo di relay attivi
        assembly {
            mstore(activeRelays, activeCount)
        }

        return activeRelays;
    }

    /**
     * @dev Calcola i MB allocati in base all'importo versato
     * @param _amount Importo in wei
     * @return uint256 MB allocati
     */
    function calculateMBFromAmount(
        uint256 _amount
    ) public pure returns (uint256) {
        // Calcola i MB: (amount * MB_PER_GB) / PRICE_PER_GB
        return (_amount * MB_PER_GB) / PRICE_PER_GB;
    }

    /**
     * @dev Calcola l'importo necessario per un numero di MB
     * @param _mb Numero di MB desiderati
     * @return uint256 Importo in wei
     */
    function calculateAmountFromMB(uint256 _mb) public pure returns (uint256) {
        // Calcola l'importo: (mb * PRICE_PER_GB) / MB_PER_GB
        return (_mb * PRICE_PER_GB) / MB_PER_GB;
    }

    /**
     * @dev Sottoscrivi a un relay
     * @param _relayAddress Indirizzo del relay
     */
    function subscribeToRelay(
        address _relayAddress
    ) external payable notPaused {
        require(
            msg.value >= MIN_SUBSCRIPTION_AMOUNT,
            "Amount too low - minimum 1 MB required"
        );
        require(relays[_relayAddress].isActive, "Relay not active");
        require(
            !isSubscriptionActive(msg.sender, _relayAddress),
            "Already subscribed to this relay"
        );

        uint256 startTime = block.timestamp;
        uint256 endTime = startTime + SUBSCRIPTION_DURATION;

        // Calcola le fee e l'importo netto per il relay
        uint256 contractFeeAmount = (msg.value * contractFee) / FEE_DENOMINATOR;
        uint256 relayAmount = msg.value - contractFeeAmount;

        // Calcola i MB basandosi su quanto riceve effettivamente il relay
        uint256 mbAllocated = calculateMBFromAmount(relayAmount);

        // Crea la sottoscrizione
        Subscription memory newSubscription = Subscription({
            user: msg.sender,
            relay: _relayAddress,
            startTime: startTime,
            endTime: endTime,
            amountPaid: msg.value,
            mbAllocated: mbAllocated,
            isActive: true
        });

        // Salva la sottoscrizione
        subscriptions[msg.sender][_relayAddress] = newSubscription;

        // Aggiorna i mapping
        userSubscriptions[msg.sender].push(_relayAddress);
        relaySubscribers[_relayAddress].push(msg.sender);

        // Trasferisci il pagamento al relay
        relays[_relayAddress].relayAddress.transfer(relayAmount);

        emit SubscriptionCreated(
            msg.sender,
            _relayAddress,
            msg.value,
            mbAllocated,
            endTime
        );
        emit PaymentDistributed(_relayAddress, relayAmount);

        if (contractFeeAmount > 0) {
            emit ContractFeeCollected(contractFeeAmount);
        }
    }

    /**
     * @dev Aggiunge MB a una sottoscrizione esistente
     * @param _relayAddress Indirizzo del relay
     */
    function addMBToSubscription(
        address _relayAddress
    ) external payable notPaused {
        require(
            msg.value >= MIN_SUBSCRIPTION_AMOUNT,
            "Amount too low - minimum 1 MB required"
        );
        require(relays[_relayAddress].isActive, "Relay not active");
        require(
            isSubscriptionActive(msg.sender, _relayAddress),
            "No active subscription found"
        );

        // Calcola le fee e l'importo netto per il relay
        uint256 contractFeeAmount = (msg.value * contractFee) / FEE_DENOMINATOR;
        uint256 relayAmount = msg.value - contractFeeAmount;

        // Calcola i MB basandosi su quanto riceve effettivamente il relay
        uint256 additionalMB = calculateMBFromAmount(relayAmount);

        // Aggiorna la sottoscrizione esistente
        Subscription storage sub = subscriptions[msg.sender][_relayAddress];
        sub.amountPaid += msg.value;
        sub.mbAllocated += additionalMB;

        // Trasferisci il pagamento al relay
        relays[_relayAddress].relayAddress.transfer(relayAmount);

        emit SubscriptionCreated(
            msg.sender,
            _relayAddress,
            msg.value,
            additionalMB,
            sub.endTime
        );
        emit PaymentDistributed(_relayAddress, relayAmount);

        if (contractFeeAmount > 0) {
            emit ContractFeeCollected(contractFeeAmount);
        }
    }

    /**
     * @dev Controlla se un utente ha una sottoscrizione attiva con un relay
     * @param _user Indirizzo dell'utente
     * @param _relayAddress Indirizzo del relay
     * @return bool True se la sottoscrizione è attiva
     */
    function isSubscriptionActive(
        address _user,
        address _relayAddress
    ) public view returns (bool) {
        Subscription memory sub = subscriptions[_user][_relayAddress];
        return sub.isActive && block.timestamp <= sub.endTime;
    }

    /**
     * @dev Ottieni i dettagli di una sottoscrizione
     * @param _user Indirizzo dell'utente
     * @param _relayAddress Indirizzo del relay
     */
    function getSubscriptionDetails(
        address _user,
        address _relayAddress
    )
        external
        view
        returns (
            uint256 startTime,
            uint256 endTime,
            uint256 amountPaid,
            uint256 mbAllocated,
            bool isActive
        )
    {
        Subscription memory sub = subscriptions[_user][_relayAddress];
        return (
            sub.startTime,
            sub.endTime,
            sub.amountPaid,
            sub.mbAllocated,
            isSubscriptionActive(_user, _relayAddress)
        );
    }

    /**
     * @dev Ottieni tutti i relay a cui un utente è sottoscritto
     * @param _user Indirizzo dell'utente
     */
    function getUserSubscriptions(
        address _user
    ) external view returns (address[] memory) {
        return userSubscriptions[_user];
    }

    /**
     * @dev Ottieni tutti gli utenti sottoscritti a un relay
     * @param _relayAddress Indirizzo del relay
     */
    function getRelaySubscribers(
        address _relayAddress
    ) external view returns (address[] memory) {
        return relaySubscribers[_relayAddress];
    }

    /**
     * @dev Ottieni i dettagli di un relay
     * @param _relayAddress Indirizzo del relay
     */
    function getRelayDetails(
        address _relayAddress
    )
        external
        view
        returns (
            string memory url,
            address relayAddress,
            bool isActive,
            uint256 registeredAt
        )
    {
        Relay memory relay = relays[_relayAddress];
        return (
            relay.url,
            relay.relayAddress,
            relay.isActive,
            relay.registeredAt
        );
    }

    /**
     * @dev Ottieni tutti i relay registrati
     */
    function getAllRelays() external view returns (address[] memory) {
        return registeredRelays;
    }

    /**
     * @dev Trova l'indirizzo di un relay basandosi sull'URL
     * @param _url URL del relay da cercare
     * @return address Indirizzo del relay se trovato, altrimenti address(0)
     */
    function findRelayByURL(
        string memory _url
    ) external view returns (address) {
        for (uint256 i = 0; i < registeredRelays.length; i++) {
            address relayAddress = registeredRelays[i];
            Relay memory relay = relays[relayAddress];
            if (
                relay.isActive &&
                keccak256(bytes(relay.url)) == keccak256(bytes(_url))
            ) {
                return relayAddress;
            }
        }
        return address(0);
    }

    /**
     * @dev Ottieni tutti i relay attivi con i loro URL
     * @return address[] Indirizzi dei relay attivi
     * @return string[] URL dei relay attivi
     */
    function getActiveRelaysWithURLs()
        external
        view
        returns (address[] memory, string[] memory)
    {
        address[] memory activeAddresses = new address[](
            registeredRelays.length
        );
        string[] memory activeURLs = new string[](registeredRelays.length);
        uint256 activeCount = 0;

        for (uint256 i = 0; i < registeredRelays.length; i++) {
            address relayAddress = registeredRelays[i];
            Relay memory relay = relays[relayAddress];
            if (relay.isActive) {
                activeAddresses[activeCount] = relayAddress;
                activeURLs[activeCount] = relay.url;
                activeCount++;
            }
        }

        // Ridimensiona gli array al numero effettivo di relay attivi
        assembly {
            mstore(activeAddresses, activeCount)
            mstore(activeURLs, activeCount)
        }

        return (activeAddresses, activeURLs);
    }

    /**
     * @dev Permette di scadere manualmente una sottoscrizione (per pulizia)
     * @param _user Indirizzo dell'utente
     * @param _relayAddress Indirizzo del relay
     */
    function expireSubscription(address _user, address _relayAddress) external {
        require(
            msg.sender == _user ||
                msg.sender == _relayAddress ||
                msg.sender == owner,
            "Not authorized to expire subscription"
        );
        require(
            subscriptions[_user][_relayAddress].isActive,
            "Subscription not active"
        );
        require(
            block.timestamp > subscriptions[_user][_relayAddress].endTime,
            "Subscription not expired yet"
        );

        subscriptions[_user][_relayAddress].isActive = false;

        emit SubscriptionExpired(_user, _relayAddress);
    }

    /**
     * @dev Modifica la fee del contratto (solo owner)
     * @param _newFee Nuova fee (in basis points, es. 200 = 2%)
     */
    function updateContractFee(uint256 _newFee) external onlyOwner {
        require(_newFee <= 1000, "Fee cannot exceed 10%"); // Max 10%
        contractFee = _newFee;
    }

    /**
     * @dev Ritira le fee accumulate (solo owner)
     */
    function withdrawFees() external onlyOwner {
        uint256 balance = address(this).balance;
        require(balance > 0, "No fees to withdraw");

        payable(owner).transfer(balance);
    }

    /**
     * @dev Trasferisce la proprietà del contratto
     * @param _newOwner Nuovo proprietario
     */
    function transferOwnership(address _newOwner) external onlyOwner {
        require(_newOwner != address(0), "New owner cannot be zero address");
        owner = _newOwner;
    }

    /**
     * @dev Funzione di emergency per pausare nuove sottoscrizioni
     */
    bool public emergencyPause = false;

    function toggleEmergencyPause() external onlyOwner {
        emergencyPause = !emergencyPause;
    }
}

contracts/security/Integrity.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title GunDBIntegrity
 * @dev Contratto minimale per verificare l'integrità dei dati GunDB
 */
contract Integrity {
    // Mapping: ID del dato -> hash originale
    mapping(bytes32 => bytes32) public dataHashes;

    // Eventi
    event DataRegistered(bytes32 indexed dataId, bytes32 dataHash);

    /**
     * @dev Registra l'hash di un dato
     * @param dataId ID univoco del dato
     * @param dataHash Hash del dato originale
     */
    function registerData(bytes32 dataId, bytes32 dataHash) external {
        require(dataHash != bytes32(0), "Hash non valido");
        require(dataHashes[dataId] == bytes32(0), "Dato gia' registrato");

        dataHashes[dataId] = dataHash;
        emit DataRegistered(dataId, dataHash);
    }

    /**
     * @dev Verifica l'integrità di un dato
     * @param dataId ID del dato
     * @param currentHash Hash attuale del dato
     * @return True se l'hash corrisponde
     */
    function verifyIntegrity(
        bytes32 dataId,
        bytes32 currentHash
    ) external view returns (bool) {
        return dataHashes[dataId] == currentHash;
    }

    /**
     * @dev Calcola l'hash di un dato
     * @param data Dati da hasciare
     * @return Hash dei dati
     */
    function calculateHash(
        bytes calldata data
    ) external pure returns (bytes32) {
        return keccak256(data);
    }
}

contracts/stealth/IPaymentForwarderHookR.content:
// SPDX-License-Identifier: MIT

pragma solidity ^0.8.24;

/// @dev Interface that post-withdraw hooks must implement to interop with Umbra
interface IPaymentForwarderHookReceiver {
  /**
   * @notice Method called after a user completes an Umbra token withdrawal
   * @param _amount The amount of the token withdrawn _after_ subtracting the sponsor fee
   * @param _stealthAddr The stealth address whose token balance was withdrawn
   * @param _acceptor Address where withdrawn funds were sent; can be this contract
   * @param _tokenAddr Address of the ERC20 token that was withdrawn
   * @param _sponsor Address which was compensated for submitting the withdrawal tx
   * @param _sponsorFee Amount of the token that was paid to the sponsor
   * @param _data Arbitrary data passed to this hook by the withdrawer
   */
  function tokensWithdrawn(
    uint256 _amount,
    address _stealthAddr,
    address _acceptor,
    address _tokenAddr,
    address _sponsor,
    uint256 _sponsorFee,
    bytes memory _data
  ) external;
}

contracts/stealth/PaymentForwarder.sol.content:
// SPDX-License-Identifier: MIT

pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "./IPaymentForwarderHookReceiver.sol";

contract PayamentForwarder is Ownable {
  // =========================================== Events ============================================

  /// @notice Emitted when a payment is sent
  event Announcement(
    address indexed receiver, // stealth address
    uint256 amount, // funds
    address indexed token, // token address or ETH placeholder
    bytes32 pkx, // ephemeral public key x coordinate
    bytes32 ciphertext // encrypted entropy and payload extension
  );

  /// @notice Emitted when a token is withdrawn
  event TokenWithdrawal(
    address indexed receiver, // stealth address
    address indexed acceptor, // destination of funds
    uint256 amount, // funds
    address indexed token // token address
  );

  // ======================================= State variables =======================================

  /// @dev Placeholder address used to identify transfer of native ETH
  address internal constant ETH_TOKEN_PLACHOLDER = 0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE;

  /// @notice An ETH amount that must be sent alongside each payment; used as an anti-spam measure
  uint256 public toll;

  /// @notice A privileged address, set by the admin, that can sweep all collected ETH tolls
  address public tollCollector;

  /// @notice The address where ETH funds are sent when collected by the tollCollector
  address payable public tollReceiver;

  /// @notice Token payments pending withdrawal; stealth address => token address => amount
  mapping(address => mapping(address => uint256)) public tokenPayments;

  // ======================================= Setup & Admin ========================================

  /**
   * @param _toll Amount of ETH required per send
   * @param _tollCollector Address that can sweep collected funds
   * @param _tollReceiver Address that receives collected funds
   */
  constructor(
    uint256 _toll,
    address _tollCollector,
    address payable _tollReceiver
  ) Ownable(msg.sender) {
    toll = _toll;
    tollCollector = _tollCollector;
    tollReceiver = _tollReceiver;
  }

  /**
   * @notice Admin only function to update the toll
   * @param _newToll New ETH toll in wei
   */
  function setToll(uint256 _newToll) external onlyOwner {
    toll = _newToll;
  }

  /**
   * @notice Admin only function to update the toll collector
   * @param _newTollCollector New address which has fund sweeping privileges
   */
  function setTollCollector(address _newTollCollector) external onlyOwner {
    tollCollector = _newTollCollector;
  }

  /**
   * @notice Admin only function to update the toll receiver
   * @param _newTollReceiver New address which receives collected funds
   */
  function setTollReceiver(address payable _newTollReceiver) external onlyOwner {
    tollReceiver = _newTollReceiver;
  }

  /**
   * @notice Function only the toll collector can call to sweep funds to the toll receiver
   */
  function collectTolls() external {
    require(msg.sender == tollCollector, "PaymentForwarder: Not toll collector");
    tollReceiver.transfer(address(this).balance);
  }

  // ======================================= Send =================================================

  /**
   * @notice Send and announce ETH payment to a stealth address
   * @param _receiver Stealth address receiving the payment
   * @param _tollCommitment Exact toll the sender is paying; should equal contract toll;
   * the committment is used to prevent frontrunning attacks by the owner;
   * see https://github.com/ScopeLift/umbra-protocol/issues/54 for more information
   * @param _pkx X-coordinate of the ephemeral public key used to encrypt the payload
   * @param _ciphertext Encrypted entropy (used to generated the stealth address) and payload extension
   */
  function sendEth(
    address payable _receiver,
    uint256 _tollCommitment,
    bytes32 _pkx, // ephemeral public key x coordinate
    bytes32 _ciphertext
  ) external payable {
    require(_tollCommitment == toll, "PaymentForwarder: Invalid or outdated toll commitment");

    // also protects from underflow
    require(msg.value > toll, "PaymentForwarder: Must pay more than the toll");

    uint256 amount = msg.value - toll;
    emit Announcement(_receiver, amount, ETH_TOKEN_PLACHOLDER, _pkx, _ciphertext);

    _receiver.transfer(amount);
  }

  /**
   * @notice Send and announce an ERC20 payment to a stealth address
   * @param _receiver Stealth address receiving the payment
   * @param _tokenAddr Address of the ERC20 token being sent
   * @param _amount Amount of the token to send, in its own base units
   * @param _pkx X-coordinate of the ephemeral public key used to encrypt the payload
   * @param _ciphertext Encrypted entropy (used to generated the stealth address) and payload extension
   */
  function sendToken(
    address _receiver,
    address _tokenAddr,
    uint256 _amount,
    bytes32 _pkx, // ephemeral public key x coordinate
    bytes32 _ciphertext
  ) external payable {
    require(msg.value == toll, "PaymentForwarder: Must pay the exact toll");
    require(tokenPayments[_receiver][_tokenAddr] == 0, "PaymentForwarder: Cannot send more tokens to stealth address");

    tokenPayments[_receiver][_tokenAddr] = _amount;
    emit Announcement(_receiver, _amount, _tokenAddr, _pkx, _ciphertext);

    SafeERC20.safeTransferFrom(IERC20(_tokenAddr), msg.sender, address(this), _amount);
  }

  // ======================================= Withdraw =============================================

  /**
   * @notice Withdraw an ERC20 token payment sent to a stealth address
   * @dev This method must be directly called by the stealth address
   * @param _acceptor Address where withdrawn funds should be sent
   * @param _tokenAddr Address of the ERC20 token being withdrawn
   */
  function withdrawToken(address _acceptor, address _tokenAddr) external {
    _withdrawTokenInternal(msg.sender, _acceptor, _tokenAddr, address(0), 0, IPaymentForwarderHookReceiver(address(0)), "");
  }

  /**
   * @notice Withdraw an ERC20 token payment sent to a stealth address
   * @dev This method must be directly called by the stealth address
   * @param _acceptor Address where withdrawn funds should be sent
   * @param _tokenAddr Address of the ERC20 token being withdrawn
   * @param _hook Contract that will be called after the token withdrawal has completed
   * @param _data Arbitrary data that will be passed to the post-withdraw hook contract
   */
  function withdrawTokenAndCall(
    address _acceptor,
    address _tokenAddr,
    IPaymentForwarderHookReceiver _hook,
    bytes memory _data
  ) external {
    _withdrawTokenInternal(msg.sender, _acceptor, _tokenAddr, address(0), 0, _hook, _data);
  }

  /**
   * @notice Withdraw an ERC20 token payment on behalf of a stealth address via signed authorization
   * @param _stealthAddr The stealth address whose token balance will be withdrawn
   * @param _acceptor Address where withdrawn funds should be sent
   * @param _tokenAddr Address of the ERC20 token being withdrawn
   * @param _sponsor Address which is compensated for submitting the withdrawal tx
   * @param _sponsorFee Amount of the token to pay to the sponsor
   * @param _v ECDSA signature component: Parity of the `y` coordinate of point `R`
   * @param _r ECDSA signature component: x-coordinate of `R`
   * @param _s ECDSA signature component: `s` value of the signature
   */
  function withdrawTokenOnBehalf(
    address _stealthAddr,
    address _acceptor,
    address _tokenAddr,
    address _sponsor,
    uint256 _sponsorFee,
    uint8 _v,
    bytes32 _r,
    bytes32 _s
  ) external {
    _validateWithdrawSignature(
      _stealthAddr,
      _acceptor,
      _tokenAddr,
      _sponsor,
      _sponsorFee,
      IPaymentForwarderHookReceiver(address(0)),
      "",
      _v,
      _r,
      _s
    );
    _withdrawTokenInternal(_stealthAddr, _acceptor, _tokenAddr, _sponsor, _sponsorFee, IPaymentForwarderHookReceiver(address(0)), "");
  }

  /**
   * @notice Withdraw an ERC20 token payment on behalf of a stealth address via signed authorization
   * @param _stealthAddr The stealth address whose token balance will be withdrawn
   * @param _acceptor Address where withdrawn funds should be sent
   * @param _tokenAddr Address of the ERC20 token being withdrawn
   * @param _sponsor Address which is compensated for submitting the withdrawal tx
   * @param _sponsorFee Amount of the token to pay to the sponsor
   * @param _hook Contract that will be called after the token withdrawal has completed
   * @param _data Arbitrary data that will be passed to the post-withdraw hook contract
   * @param _v ECDSA signature component: Parity of the `y` coordinate of point `R`
   * @param _r ECDSA signature component: x-coordinate of `R`
   * @param _s ECDSA signature component: `s` value of the signature
   */
  function withdrawTokenAndCallOnBehalf(
    address _stealthAddr,
    address _acceptor,
    address _tokenAddr,
    address _sponsor,
    uint256 _sponsorFee,
    IPaymentForwarderHookReceiver _hook,
    bytes memory _data,
    uint8 _v,
    bytes32 _r,
    bytes32 _s
  ) external {
    _validateWithdrawSignature(_stealthAddr, _acceptor, _tokenAddr, _sponsor, _sponsorFee, _hook, _data, _v, _r, _s);
    _withdrawTokenInternal(_stealthAddr, _acceptor, _tokenAddr, _sponsor, _sponsorFee, _hook, _data);
  }

  /**
   * @notice Low level withdrawal function that should only be called after safety checks
   * @param _stealthAddr The stealth address whose token balance will be withdrawn
   * @param _acceptor Address where withdrawn funds should be sent
   * @param _tokenAddr Address of the ERC20 token being withdrawn
   * @param _sponsor Address which is compensated for submitting the withdrawal tx
   * @param _sponsorFee Amount of the token to pay to the sponsor
   * @param _hook Contract that will be called after the token withdrawal has completed
   * @param _data Arbitrary data that will be passed to the post-withdraw hook contract
   */
  function _withdrawTokenInternal(
    address _stealthAddr,
    address _acceptor,
    address _tokenAddr,
    address _sponsor,
    uint256 _sponsorFee,
    IPaymentForwarderHookReceiver _hook,
    bytes memory _data
  ) internal {
    uint256 _amount = tokenPayments[_stealthAddr][_tokenAddr];

    // also protects from underflow
    require(_amount > _sponsorFee, "PaymentForwarder: No balance to withdraw or fee exceeds balance");

    uint256 _withdrawalAmount = _amount - _sponsorFee;
    delete tokenPayments[_stealthAddr][_tokenAddr];
    emit TokenWithdrawal(_stealthAddr, _acceptor, _withdrawalAmount, _tokenAddr);

    SafeERC20.safeTransfer(IERC20(_tokenAddr), _acceptor, _withdrawalAmount);

    if (_sponsorFee > 0) {
      SafeERC20.safeTransfer(IERC20(_tokenAddr), _sponsor, _sponsorFee);
    }

    if (address(_hook) != address(0)) {
      _hook.tokensWithdrawn(_withdrawalAmount, _stealthAddr, _acceptor, _tokenAddr, _sponsor, _sponsorFee, _data);
    }
  }

  /**
   * @notice Internal method which recovers address from signature of the parameters and throws if not _stealthAddr
   * @param _stealthAddr The stealth address whose token balance will be withdrawn
   * @param _acceptor Address where withdrawn funds should be sent
   * @param _tokenAddr Address of the ERC20 token being withdrawn
   * @param _sponsor Address which is compensated for submitting the withdrawal tx
   * @param _sponsorFee Amount of the token to pay to the sponsor
   * @param _hook Contract that will be called after the token withdrawal has completed
   * @param _data Arbitrary data that will be passed to the post-withdraw hook contract
   * @param _v ECDSA signature component: Parity of the `y` coordinate of point `R`
   * @param _r ECDSA signature component: x-coordinate of `R`
   * @param _s ECDSA signature component: `s` value of the signature
   */
  function _validateWithdrawSignature(
    address _stealthAddr,
    address _acceptor,
    address _tokenAddr,
    address _sponsor,
    uint256 _sponsorFee,
    IPaymentForwarderHookReceiver _hook,
    bytes memory _data,
    uint8 _v,
    bytes32 _r,
    bytes32 _s
  ) internal view {
    uint256 _chainId;
    assembly {
      _chainId := chainid()
    }

    bytes32 _digest =
      keccak256(
        abi.encodePacked(
          "\x19Ethereum Signed Message:\n32",
          keccak256(
            abi.encode(_chainId, address(this), _acceptor, _tokenAddr, _sponsor, _sponsorFee, address(_hook), _data)
          )
        )
      );

    address _recoveredAddress = ecrecover(_digest, _v, _r, _s);
    require(_recoveredAddress != address(0) && _recoveredAddress == _stealthAddr, "PaymentForwarder: Invalid Signature");
  }
}

